  'gov-endorse': [W('Zertifizieren kann jede Besitzerin selbst. Höherstufen dürfen nur Admins nach einer Prüfung.','Owners can certify themselves. Only admins may promote after a review.'), W('Beides vergibt Microsoft automatisch anhand der Nutzungszahlen eines Semantikmodells.','Microsoft assigns both automatically based on a semantic model\'s usage numbers.'), W('Höhergestuft heißt veraltet, zertifiziert heißt aktuell. Beides setzt der Refresh selbst.','Promoted means outdated, certified means current. The refresh sets both itself.')],
  'gov-label': [W('Row-Level Security, die auch in der exportierten Excel-Datei filtert','Row-level security that keeps filtering in the exported Excel file'), W('Die Betrachter-Rolle des Workspace, die auch für Exporte gilt','The workspace viewer role, which also applies to exports'), W('Ein Wasserzeichen „Vertraulich“, das in jeden Export eingebettet wird','A "Confidential" watermark embedded into every export')],
  'gov-selfservice': [W('Jeder Fachbereich baut eigene Modelle, die IT prüft einmal im Jahr alle Zahlen','Each department builds its own models, IT checks all numbers once a year'), W('Alle Berichte baut zentral die IT, Fachbereiche bekommen nur PDF-Exporte','IT builds all reports centrally, departments only get PDF exports'), W('Self-Service bleibt in Excel, nur die fertigen Ergebnisse kommen nach Power BI','Self-service stays in Excel, only final results go to Power BI')],
  'gov-deploy': [W('Einen zweiten Admin einstellen, der jede Änderung vor dem Speichern abnickt','Hire a second admin who signs off every single change before it is saved'), W('Versionsnummern in den Berichtstitel schreiben und alte Kopien behalten','Put version numbers into report titles and keep all the old copies around'), W('Änderungen nur noch nachts veröffentlichen, wenn niemand Berichte nutzt','Only publish changes late at night when nobody is using the reports')],
  'inc-cred': [W('Die Faktentabelle passt nicht mehr ins Refresh-Zeitfenster','The fact table no longer fits into the refresh window'), W('Die SQL-Tabelle wurde umbenannt, Abfrage anpassen','The SQL table was renamed, adjust the query'), W('Das Gateway ist offline, Gateway-Dienst neu starten','The gateway is offline, restart the gateway service')],
