  'inc-type': [W('Die Zahl ist zu groß für den Datentyp, auf Festkommazahl wechseln.','The number is too big for the type, switch to fixed decimal.'), W('Die Spalte wurde in der Quelle gelöscht, der Schritt findet keine Werte.','The column was deleted in the source, the step finds no values.'), W('Die Datei ist gesperrt, weil jemand sie gerade in Excel geöffnet hat.','The file is locked because someone has it open in Excel.')],
  'inc-gw': [W('Das Passwort der Datenquelle ist abgelaufen und muss erneuert werden','The data source password expired and must be renewed'), W('Die Kapazität ist überlastet und lehnt neue Verbindungen ab','The capacity is overloaded and rejects new connections'), W('Die Datenquelle wurde umbenannt, der Pfad im Bericht stimmt nicht','The data source was renamed, the path in the report is wrong')],
  'inc-throttle': [W('OneLake-Speicher voll, alte Delta-Versionen per VACUUM aufräumen','OneLake storage full, clean up old Delta versions with VACUUM'), W('Gateway überlastet, einen zweiten Gateway-Knoten hinzufügen','Gateway overloaded, add a second gateway node'), W('Zu viele Nutzer, Lizenzen von Pro auf PPU umstellen','Too many users, switch licenses from Pro to PPU')],
  'inc-timeout': [W('Den Refresh in zwei Hälften teilen und zweimal täglich starten','Split the refresh in two halves and run it twice a day'), W('Alle Textspalten in Zahlen umwandeln, das spart Ladezeit','Convert all text columns to numbers to save load time'), W('Den Zeitplan auf drei Uhr nachts verschieben, dann ist mehr Zeit','Move the schedule to 3 am, then there is more time')],
  'dax-filterctx': [W('Das Measure wird pro Zeile als Wert in der Tabelle gespeichert und gelesen.','The measure is stored as a value per row in the table and read back.'), W('Jede Zeile hat einen Zeilenkontext, den das Measure automatisch übernimmt.','Each row has a row context that the measure automatically picks up.'), W('Das Visual summiert erst am Ende, das Measure liefert nur Einzelwerte.','The visual sums at the end, the measure only returns single values.')],
