  'dax-totals': [W('Die Summenzeile summiert nur sichtbare Zeilen, ausgeblendete fehlen.','The total row only sums visible rows, hidden ones are missing.'), W('Die Summenzeile nutzt den Zeilenkontext der letzten Zeile im Visual.','The total row uses the row context of the visual\'s last row.'), W('Summenzeilen ignorieren Measures und addieren die Spalte darunter.','Total rows ignore measures and add up the column underneath.')],
  'dax-iterator': [W('Das Measure als berechnete Spalte in Sales anlegen und die Beziehung bidirektional machen','Create the measure as a calculated column in Sales and make the relationship bidirectional'), W('SUMX durch SUM ersetzen und RELATED weglassen, der Preis wird automatisch gefunden','Replace SUMX with SUM and drop RELATED, the price is found automatically'), W('Die Produkttabelle per DirectQuery anbinden, damit RELATED live nachschlägt','Connect the product table via DirectQuery so RELATED looks up live')],
  'pq-reference': [W('Verweis kopiert alle Schritte, Duplizieren baut auf dem Ergebnis der Abfrage auf.','Reference copies all steps, Duplicate builds on the query\'s result.'), W('Beides kopiert die Daten physisch, Verweis lädt sie nur schneller ins Modell.','Both copy the data physically, Reference just loads it faster.'), W('Verweis ist schreibgeschützt, Duplizieren lässt sich danach frei bearbeiten.','Reference is read-only, Duplicate can be edited freely afterwards.')],
  'pq-locale': [W('Typ auf Datum/Uhrzeit/Zeitzone ändern und UTC wählen','Change type to date/time/timezone and pick UTC'), W('Windows-Sprache auf Englisch (USA) umstellen','Switch the Windows language to English (US)'), W('Das Datum als Zahl laden und im Modell formatieren','Load the date as a number and format it in the model')],
  'pq-groupby': [W('Pivotieren mit Kunde als Spaltenüberschrift','Pivot with customer as column header'), W('Zusammenführen mit sich selbst über KundeID','Merge with itself on customer ID'), W('Duplikate entfernen und Zeilen zählen lassen','Remove duplicates and count rows')],
