/* ---------- Due Diligence vor einer Übernahme ---------- */
const DD = (id, c, q, o, x) => Q(id, c, 2, q, o, x, { pool: 'dd' });
QUIZ.push(
DD('dd-cluster', 'gov', W('Der Rivale meldet 40 Betriebsverträge, 31 davon mit einem einzigen Konzern. Wie bewertest du das?', 'The rival reports 40 retainers, 31 of them with one single corporation. How do you rate that?'),
  [W('Klumpenrisiko: Kündigt der Konzern, bricht der Umsatz weg. Preis senken.', 'Concentration risk: if the corporation cancels, revenue collapses. Lower the price.'),
   W('Ideal: Ein großer Kunde heißt planbare Umsätze und kaum Vertriebskosten.', 'Ideal: one big client means predictable revenue and hardly any sales costs.'),
   W('Unwichtig: Bei Übernahmen zählt nur die Zahl der Verträge, nicht der Kunde.', 'Irrelevant: in takeovers only the number of contracts counts, not the client.'),
   W('Positiv: Konzernverträge laufen gesetzlich mindestens zehn Jahre weiter.', 'Positive: corporate contracts legally run for at least ten more years.')],
  W('Abhängigkeit von einem Kunden ist eines der größten Risiken beim Kauf einer Beratung. Es gehört in den Preis oder in Garantien.', 'Dependence on one client is one of the biggest risks when buying a consultancy. It belongs in the price or in guarantees.')),
DD('dd-models', 'model', W('Die Kundenberichte des Rivalen nutzen 140 Semantikmodelle, jedes mit eigener Kopie der Umsatzlogik. Was heißt das für dich?', 'The rival\'s client reports use 140 semantic models, each with its own copy of the revenue logic. What does that mean for you?'),
  [W('Hohe Wartungslast und widersprüchliche Zahlen, Konsolidierung einpreisen', 'High maintenance load and conflicting numbers, price in a consolidation'),
   W('Gut: Viele unabhängige Modelle sind besonders stabil und ausfallsicher', 'Good: many independent models are especially stable and resilient'),
   W('Egal: Copilot gleicht unterschiedliche Logiken automatisch miteinander ab', 'Irrelevant: Copilot automatically reconciles different logics with each other'),
   W('Ein Qualitätsmerkmal, weil jeder Bericht genau maßgeschneidert ist', 'A sign of quality, because every report is precisely tailor-made')],
  W('Kopierte Logik driftet auseinander. Nach dem Kauf zahlst du die Zusammenführung, also gehört sie in die Bewertung.', 'Copied logic drifts apart. After the purchase you pay for merging it, so it belongs in the valuation.')),
DD('dd-keyperson', 'team', W('Das gesamte Fabric-Wissen des Rivalen liegt bei einer Person, die nach der Übernahme gehen will. Bewertung?', 'All of the rival\'s Fabric knowledge sits with one person who wants to leave after the takeover. Assessment?'),
  [W('Schlüsselpersonen-Risiko: Bleibeprämie oder Übergabe vertraglich sichern', 'Key-person risk: secure a retention bonus or handover in the contract'),
   W('Kein Problem: Wissen steckt ja in den Dateien und bleibt automatisch da', 'No problem: the knowledge is in the files and stays there automatically'),
   W('Vorteil: Eine teure Person weniger senkt sofort die Gehaltskosten', 'Advantage: one expensive person less immediately lowers salary costs'),
   W('Unwichtig: Fabric-Wissen lässt sich in einer Woche neu aufbauen', 'Irrelevant: Fabric knowledge can be rebuilt within a single week')],
  W('Bei Beratungen kaufst du vor allem Köpfe. Wer zentrale Leute verliert, hat Verträge ohne Lieferfähigkeit gekauft.', 'With consultancies you mainly buy people. Lose the key people and you bought contracts without delivery capacity.')),
DD('dd-licenses', 'gov', W('In den Unterlagen fehlen Nachweise für 60 Pro-Lizenzen, geteilt werden die Berichte aber trotzdem. Was prüfst du?', 'The documents lack proof of 60 Pro licenses, yet reports are shared anyway. What do you check?'),
  [W('Ob Lizenzen fehlen: Nachzahlungen und Compliance-Risiko einpreisen', 'Whether licenses are missing: price in back payments and compliance risk'),
   W('Nichts, Lizenzen gehen bei Übernahmen automatisch kostenlos über', 'Nothing, licenses transfer automatically and free of charge in takeovers'),
   W('Nur die Farbe des Logos, Lizenzen sind Sache der Microsoft-Partner', 'Only the logo color, licenses are the Microsoft partners\' business'),
   W('Ob die Berichte hübsch genug sind, Lizenzen klären sich später', 'Whether the reports are pretty enough, licenses sort themselves out later')],
  W('Unterlizenzierung ist eine Altlast, die mit dem Kauf zu dir wandert. Prüfen, beziffern, im Preis oder per Garantie absichern.', 'Under-licensing is a legacy issue that moves to you with the purchase. Check it, quantify it, cover it in the price or with a guarantee.')),
DD('dd-gateway', 'fabric', W('Alle Kundenberichte des Rivalen laufen über ein persönliches Gateway auf einem Laptop. Risiko?', 'All of the rival\'s client reports run through a personal gateway on one laptop. Risk?'),
  [W('Ausfall- und Sicherheitsrisiko: auf ein Standard-Gateway umstellen', 'Outage and security risk: move to a standard gateway'),
   W('Keins: Persönliche Gateways sind für Kunden extra zertifiziert', 'None: personal gateways are specially certified for clients'),
   W('Ein Vorteil: Laptops sind mobil und deshalb besonders ausfallsicher', 'An advantage: laptops are mobile and therefore especially resilient'),
   W('Nur ein Lizenzthema, technisch ist das genau wie ein Server', 'Only a licensing topic, technically it is just like a server')],
  W('Ist der Laptop zu oder weg, stehen alle Aktualisierungen. Ein persönliches Gateway ist für Einzelne gedacht, nicht für Kundenbetrieb.', 'If the laptop is closed or gone, all refreshes stop. A personal gateway is meant for individuals, not for client operations.')),
DD('dd-oneoff', 'talk', W('Der Umsatz des Rivalen stieg im letzten Quartal um 80 %, allein durch einmalige Workshops. Wie bewertest du das?', 'The rival\'s revenue rose 80 % last quarter, solely from one-off workshops. How do you rate that?'),
  [W('Nicht wiederkehrend: Für den Preis zählen vor allem stabile Erträge', 'Not recurring: for the price, stable earnings matter most'),
   W('Hervorragend: Das Wachstum lässt sich einfach fortschreiben', 'Excellent: the growth can simply be extrapolated forward'),
   W('Egal: Umsatz ist Umsatz, die Herkunft spielt keine Rolle', 'Irrelevant: revenue is revenue, the source does not matter'),
   W('Ein Grund, sofort zum doppelten Preis zuzuschlagen', 'A reason to buy right away at double the price')],
  W('Einmaleffekte schönen die Zahlen. Wiederkehrende Betriebsverträge sind wertvoller als ein starkes Workshop-Quartal.', 'One-off effects flatter the numbers. Recurring retainers are worth more than one strong workshop quarter.')),
DD('dd-passwords', 'sql', W('Die Kundendatenbank des Rivalen speichert Passwörter im Klartext. Konsequenz?', 'The rival\'s client database stores passwords in plain text. Consequence?'),
  [W('Sicherheits- und Datenschutzproblem: vor dem Kauf beheben und Haftung klären', 'Security and privacy problem: fix before purchase and settle liability'),
   W('Praktisch, so kann der Support vergessene Passwörter direkt nachlesen', 'Handy, that way support can look up forgotten passwords directly'),
   W('Unkritisch, solange die Datenbank in einem deutschen Rechenzentrum steht', 'Uncritical as long as the database sits in a German data center'),
   W('Ein reines Performance-Thema, Verschlüsselung würde alles verlangsamen', 'Purely a performance topic, encryption would slow everything down')],
  W('Passwörter gehören gehasht, nie im Klartext gespeichert. Ein Datenleck nach dem Kauf wäre dein Problem, also vorher klären.', 'Passwords must be hashed, never stored in plain text. A breach after the purchase would be your problem, so settle it first.')),
DD('dd-nodocs', 'dax', W('Beim Rivalen gibt es keine Doku, keine Git-Historie und keine Beschreibungen an den Measures. Was heißt das?', 'At the rival there are no docs, no Git history and no descriptions on measures. What does that mean?'),
  [W('Hohe Einarbeitungskosten und Risiko bei Änderungen, Abschlag beim Preis', 'High onboarding cost and risk with changes, a discount on the price'),
   W('Schlanke Prozesse, ohne Doku arbeitet man nachweislich schneller', 'Lean processes, without docs people demonstrably work faster'),
   W('Nichts, Measures erklären sich durch ihren Namen von ganz allein', 'Nothing, measures explain themselves through their names alone'),
   W('Ein gutes Zeichen, weil nie etwas geändert werden musste', 'A good sign, because nothing ever needed to be changed')],
  W('Ohne Doku und Versionsgeschichte kostet jede Änderung Detektivarbeit. Das ist technische Schuld, und die kaufst du mit.', 'Without docs and version history every change costs detective work. That is technical debt, and you buy it along.')),
);

/* ---------- SQL-Lückentexte (c:'sql') ---------- */
FILL.push(
{ id:'fill-sql-join', c:'sql', d:1, title:{de:'Alle Kunden mit Umsatz, auch ohne Bestellung',en:'All customers with revenue, even without orders'},
  code:{de:'SELECT k.Name, SUM(b.Betrag) AS Umsatz\nFROM Kunde k\n{0} JOIN Bestellung b ON b.KundeID = k.KundeID\n{1} k.Name', en:'SELECT c.Name, SUM(o.Amount) AS Revenue\nFROM Customer c\n{0} JOIN Orders o ON o.CustomerID = c.CustomerID\n{1} c.Name'},
  blanks:[{o:['LEFT','INNER','CROSS'],a:0},{o:['GROUP BY','ORDER BY','SPLIT BY'],a:0}],
  x:{de:'LEFT JOIN behält Kunden ohne Bestellung (Umsatz NULL). GROUP BY fasst je Kunde zusammen, ORDER BY würde nur sortieren.',en:'LEFT JOIN keeps customers without orders (revenue NULL). GROUP BY aggregates per customer, ORDER BY would only sort.'} },
{ id:'fill-sql-having', c:'sql', d:2, title:{de:'Kunden mit mehr als zehn Bestellungen',en:'Customers with more than ten orders'},
  code:{de:'SELECT KundeID, COUNT(*) AS Anzahl\nFROM Bestellung\n{0} KundeID\n{1} COUNT(*) > 10', en:'SELECT CustomerID, COUNT(*) AS Cnt\nFROM Orders\n{0} CustomerID\n{1} COUNT(*) > 10'},
  blanks:[{o:['GROUP BY','ORDER BY','PARTITION BY'],a:0},{o:['HAVING','WHERE','FILTER'],a:0}],
  x:{de:'Bedingungen auf Aggregaten wie COUNT(*) gehören ins HAVING, denn WHERE läuft vor dem Gruppieren und kennt die Anzahl noch nicht.',en:'Conditions on aggregates like COUNT(*) belong in HAVING, because WHERE runs before grouping and does not know the count yet.'} },
{ id:'fill-sql-last', c:'sql', d:2, title:{de:'Die jeweils letzte Bestellung je Kunde',en:'The latest order per customer'},
  code:{de:'WITH letzte AS (\n  SELECT KundeID, Datum,\n    ROW_NUMBER() OVER (PARTITION BY KundeID ORDER BY Datum {0}) AS rn\n  FROM Bestellung\n)\nSELECT * FROM letzte WHERE rn {1} 1', en:'WITH latest AS (\n  SELECT CustomerID, OrderDate,\n    ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY OrderDate {0}) AS rn\n  FROM Orders\n)\nSELECT * FROM latest WHERE rn {1} 1'},
  blanks:[{o:['DESC','ASC','NULLS FIRST'],a:0},{o:['=','>','<>'],a:0}],
  x:{de:'ROW_NUMBER nummeriert je Kunde, absteigend nach Datum bekommt die neueste Bestellung die 1. Ein Klassiker für „letzter Stand je Schlüssel“.',en:'ROW_NUMBER numbers per customer, descending by date gives the newest order number 1. A classic for "latest state per key".'} },
{ id:'fill-sql-rank', c:'sql', d:3, title:{de:'Rang der Produkte innerhalb ihrer Kategorie',en:'Product rank within its category'},
  code:{de:'SELECT Produkt, Kategorie, Umsatz,\n  {0}() OVER ({1} Kategorie ORDER BY Umsatz DESC) AS Rang\nFROM ProduktUmsatz', en:'SELECT Product, Category, Revenue,\n  {0}() OVER ({1} Category ORDER BY Revenue DESC) AS Rnk\nFROM ProductRevenue'},
  blanks:[{o:['RANK','COUNT','LAST'],a:0},{o:['PARTITION BY','DISTRIBUTE BY','GROUP BY ALL'],a:0}],
  x:{de:'RANK vergibt bei Gleichstand denselben Rang und lässt danach Lücken, DENSE_RANK nicht. PARTITION BY startet die Zählung je Kategorie neu.',en:'RANK gives ties the same rank and then leaves gaps, DENSE_RANK does not. PARTITION BY restarts the count per category.'} },
);

/* ---------- Reihenfolgen für SQL und Team ---------- */
ORDER.push(
{ id:'ord-sql-exec', c:'sql', title:{de:'In welcher Reihenfolge wertet die Datenbank eine Abfrage aus?',en:'In which order does the database evaluate a query?'},
  steps:[{de:'FROM und JOIN: Tabellen verbinden',en:'FROM and JOIN: combine tables'},{de:'WHERE: Zeilen filtern',en:'WHERE: filter rows'},{de:'GROUP BY: gruppieren',en:'GROUP BY: group'},{de:'HAVING: Gruppen filtern',en:'HAVING: filter groups'},{de:'SELECT: Spalten und Ausdrücke',en:'SELECT: columns and expressions'},{de:'ORDER BY: sortieren',en:'ORDER BY: sort'}],
  x:{de:'Geschrieben wird SELECT zuerst, ausgewertet aber fast zuletzt. Deshalb kennt WHERE die Aliasnamen aus dem SELECT noch nicht, ORDER BY dagegen schon.',en:'SELECT is written first but evaluated almost last. That is why WHERE does not know SELECT aliases yet, while ORDER BY does.'} },
{ id:'ord-sql-mirror', c:'sql', title:{de:'Eine Datenbank nach Fabric spiegeln',en:'Mirror a database into Fabric'},
  steps:[{de:'Mirroring-Element anlegen und mit der Datenbank verbinden',en:'Create a mirroring item and connect it to the database'},{de:'Tabellen für die Spiegelung auswählen',en:'Select the tables to mirror'},{de:'Erste Vollkopie abwarten',en:'Wait for the initial full copy'},{de:'Änderungen laufen fortlaufend nach OneLake',en:'Changes flow continuously into OneLake'},{de:'Über SQL-Endpunkt, Shortcut oder Direct Lake nutzen',en:'Use via SQL endpoint, shortcut or Direct Lake'}],
  x:{de:'Erst die Vollkopie, dann nur noch Änderungen. Die gespiegelten Tabellen sind Delta und damit für alle Fabric-Werkzeuge lesbar.',en:'First the full copy, then only changes. Mirrored tables are Delta and thus readable by every Fabric tool.'} },
{ id:'ord-team-retro', c:'team', title:{de:'Ablauf einer Retrospektive',en:'Flow of a retrospective'},
  steps:[{de:'Rahmen setzen und das Ziel nennen',en:'Set the stage and name the goal'},{de:'Daten sammeln: was lief gut, was nicht?',en:'Gather data: what went well, what did not?'},{de:'Ursachen gemeinsam verstehen',en:'Understand causes together'},{de:'Ein bis zwei konkrete Maßnahmen beschließen',en:'Decide one or two concrete actions'},{de:'Abschließen und Maßnahmen nachhalten',en:'Close and follow up on the actions'}],
  x:{de:'Wer direkt bei Maßnahmen startet, löst die falschen Probleme. Erst sammeln, dann verstehen, dann entscheiden.',en:'Jumping straight to actions solves the wrong problems. Gather first, then understand, then decide.'} },
{ id:'ord-team-feedback', c:'team', title:{de:'Feedback geben, das ankommt',en:'Giving feedback that lands'},
  steps:[{de:'Die konkrete Situation benennen',en:'Name the concrete situation'},{de:'Das beobachtete Verhalten beschreiben',en:'Describe the observed behavior'},{de:'Die Wirkung schildern',en:'Explain the impact'},{de:'Gemeinsam den nächsten Schritt vereinbaren',en:'Agree on the next step together'}],
  x:{de:'Situation, Verhalten, Wirkung: Beobachtung statt Urteil. Der gemeinsame nächste Schritt macht aus Kritik eine Verabredung.',en:'Situation, behavior, impact: observation instead of judgment. The shared next step turns criticism into an agreement.'} },
);

/* ---------- Teamgespräche (c:'team') ---------- */
DIALOGS.push(
{ id:'dlg-team-late', c:'team', who:{de:'Junior-Beraterin „Jana Neu“',en:'Junior consultant "Jana New"'}, av:'JN',
  steps:[
   {say:{de:'„Sorry, der Bericht für Bäckerei Krümel ist schon wieder nicht fertig. Ich hänge an den Measures.“',en:'"Sorry, the report for Krümel Bakery is not done again. I am stuck on the measures."'},
    a:[{t:{de:'„Danke, dass du es sagst. Wo genau hängst du? Lass uns 20 Minuten zusammen draufschauen.“',en:'"Thanks for telling me. Where exactly are you stuck? Let us look at it together for 20 minutes."'},s:1,f:{de:'Du machst das Problem besprechbar und hilfst konkret. So lernt sie, früher Bescheid zu sagen.',en:'You make the problem discussable and help concretely. That teaches her to speak up earlier.'}},
       {t:{de:'„Schon wieder? Dann bleib heute halt länger, bis es fertig ist. Ist ja dein Auftrag.“',en:'"Again? Then just stay late today until it is done. It is your assignment after all."'},s:.1,f:{de:'Druck ohne Hilfe. Beim nächsten Mal sagt sie gar nichts mehr.',en:'Pressure without help. Next time she will not say anything at all.'}},
       {t:{de:'„Gib her, ich mach das schnell selbst fertig. Du kannst dich um etwas anderes kümmern.“',en:'"Give it here, I will quickly finish it myself. You can take care of something else."'},s:.3,f:{de:'Kurzfristig schnell, aber sie lernt nichts und du wirst zum Engpass.',en:'Quick in the short run, but she learns nothing and you become the bottleneck.'}}]},
   {say:{de:'„Ehrlich gesagt verstehe ich CALCULATE nicht richtig und habe mich nicht getraut zu fragen.“',en:'"Honestly, I do not really understand CALCULATE and did not dare to ask."'},
    a:[{t:{de:'„Gut, dass du es sagst. Ich zeige dir das Prinzip, und ab jetzt gibt es jeden Freitag eine Fragerunde.“',en:'"Good that you say it. I will show you the principle, and from now on there is a Q&A slot every Friday."'},s:1,f:{de:'Wissenslücke geschlossen und ein fester Rahmen geschaffen, in dem Fragen normal sind.',en:'Knowledge gap closed and a fixed space created where questions are normal.'}},
       {t:{de:'„Das ist aber Grundwissen. Schau dir bitte am Wochenende ein paar Videos dazu an.“',en:'"That is basic knowledge though. Please watch a few videos on it over the weekend."'},s:.2,f:{de:'Abwertend und ohne Unterstützung. Die Angst vor Fragen wächst.',en:'Dismissive and without support. The fear of asking grows.'}},
       {t:{de:'„Kein Problem, dann nimmst du ab jetzt nur noch Aufträge ohne DAX, das ist einfacher.“',en:'"No problem, from now on you only take on jobs without any DAX in them, that is much easier for you."'},s:.3,f:{de:'Gut gemeint, aber du hältst sie klein, statt sie wachsen zu lassen.',en:'Well meant, but you keep her small instead of letting her grow.'}}]},
  ]},
{ id:'dlg-team-clash', c:'team', who:{de:'Senior-Berater „Sam Sicher“',en:'Senior consultant "Sam Sure"'}, av:'SS',
  steps:[
   {say:{de:'„Kim baut die Berechnungen in Power Query, ich in DAX. Jetzt haben wir zwei Umsatzzahlen. Kim hört einfach nicht zu.“',en:'"Kim builds the calculations in Power Query, I build them in DAX. Now we have two revenue numbers. Kim just does not listen."'},
    a:[{t:{de:'„Setzen wir uns zu dritt hin und legen Kriterien fest, wo welche Berechnung hingehört.“',en:'"Let us sit down, the three of us, and set criteria for where which calculation belongs."'},s:1,f:{de:'Vom Personen- zum Sachkonflikt. Gemeinsame Regeln verhindern den nächsten Streit.',en:'From a personal to a factual conflict. Shared rules prevent the next argument.'}},
       {t:{de:'„Du bist der Senior, also gilt deine Lösung. Ich sage Kim, dass sie es umbauen soll.“',en:'"You are the senior, so your solution counts. I will tell Kim to rebuild it."'},s:.2,f:{de:'Hierarchie statt Argumente. Kim fühlt sich übergangen.',en:'Hierarchy instead of arguments. Kim feels overruled.'}},
       {t:{de:'„Klärt das bitte unter euch, ich habe gerade wirklich keine Zeit für solche Diskussionen.“',en:'"Please sort it out between you, I truly have no time for such discussions right now."'},s:0,f:{de:'Der Konflikt eskaliert weiter, und der Kunde sieht zwei Zahlen.',en:'The conflict escalates and the client sees two numbers.'}}]},
   {say:{de:'„Und wer erklärt dem Kunden jetzt, warum letzte Woche zwei verschiedene Zahlen im Bericht standen?“',en:'"And who explains to the client now why there were two different numbers in the report last week?"'},
    a:[{t:{de:'„Ich übernehme das. Wir nennen die Ursache offen und zeigen, wie wir es künftig verhindern.“',en:'"I will take it. We name the cause openly and show how we prevent it in future."'},s:1,f:{de:'Verantwortung übernehmen und Lösung zeigen schafft beim Kunden mehr Vertrauen als Schweigen.',en:'Taking responsibility and showing the fix builds more client trust than silence.'}},
       {t:{de:'„Am besten gar nicht. Vielleicht ist es dem Kunden ja überhaupt nicht aufgefallen.“',en:'"Ideally nobody. Maybe the client did not notice it at all."'},s:.1,f:{de:'Es fällt immer auf. Spätestens im Monatsabschluss.',en:'It always gets noticed. At the latest in the month-end close.'}},
       {t:{de:'„Kim soll es erklären, schließlich hat sie die zweite Zahl überhaupt erst gebaut.“',en:'"Kim should explain it, after all she built the second number in the first place."'},s:.2,f:{de:'Schuld zuweisen spaltet das Team, und der Kunde merkt es.',en:'Assigning blame splits the team, and the client notices.'}}]},
  ]},
{ id:'dlg-team-yes', c:'team', who:{de:'Beraterin „Frau Allesgleichzeitig“',en:'Consultant "Ms. Alltheatonce"'}, av:'AG',
  steps:[
   {say:{de:'„Ich habe noch drei Aufträge zugesagt. Das schaffe ich schon irgendwie, ich schlafe halt weniger.“',en:'"I said yes to three more jobs. I will manage somehow, I will just sleep less."'},
    a:[{t:{de:'„Lass uns deine Liste anschauen und gemeinsam entscheiden, was warten kann oder wer übernimmt.“',en:'"Let us look at your list and decide together what can wait or who takes over."'},s:1,f:{de:'Du nimmst die Überlastung ernst und hilfst beim Priorisieren statt zu loben.',en:'You take the overload seriously and help prioritize instead of praising.'}},
       {t:{de:'„Super Einsatz! Genau solche Leute brauchen wir hier, mach weiter so.“',en:'"Great commitment! We need exactly people like you, keep it up."'},s:0,f:{de:'Du belohnst den Weg in den Burnout.',en:'You reward the road to burnout.'}},
       {t:{de:'„Dann sag bitte allen drei Kunden sofort wieder ab, so kann das auf keinen Fall weitergehen.“',en:'"Then please cancel all three clients right away, this cannot go on."'},s:.3,f:{de:'Richtiger Impuls, aber ohne Plan verärgerst du drei Kunden auf einmal.',en:'Right impulse, but without a plan you upset three clients at once.'}}]},
   {say:{de:'„Aber wenn ich Nein sage, wirkt das doch so, als würde ich mich nicht reinhängen.“',en:'"But if I say no, it looks like I am not committed."'},
    a:[{t:{de:'„Ein begründetes Nein ist Professionalität. Ich stärke dir dabei den Rücken.“',en:'"A reasoned no is professionalism. I will back you up on it."'},s:1,f:{de:'Rückendeckung macht Grenzen setzen möglich. Das schützt Person und Qualität.',en:'Backing makes setting limits possible. It protects person and quality.'}},
       {t:{de:'„Stimmt schon, Nein sagen kommt bei Kunden nie besonders gut an.“',en:'"True, saying no never goes down well with clients."'},s:.1,f:{de:'Du bestätigst die Angst, statt sie aufzulösen.',en:'You confirm the fear instead of dissolving it.'}},
       {t:{de:'„Dann sag halt Ja und gib die Aufgaben heimlich an die Juniors weiter.“',en:'"Then just say yes and secretly pass the tasks on to the juniors."'},s:.2,f:{de:'Verschiebt das Problem nur, und Kunden merken den Qualitätsverlust.',en:'Only shifts the problem, and clients notice the drop in quality.'}}]},
  ]},
);

/* ---------- Weitere Lernkarten ---------- */
